INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 14, 'theory', 'Web APIs: REST, WebSocket, Server-Sent Events and gRPC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 0, 'Which status code should be returned when a POST successfully creates a resource?', '["200 OK with no headers", "204 No Content", "302 Found", "201 Created with a Location header holding the new resource''s address"]', 3, '201 says the resource was created, and Location gives its address.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 1, 'What is an idempotency key (Idempotency-Key) for?', '["So that retrying a POST after a lost response does not create a duplicate", "To encrypt the request", "To speed up the response", "To limit the request rate"]', 0, 'The second time, the server returns the saved result for the same key.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 2, 'A client has exceeded the request limit. What response do we expect?', '["401 Unauthorized", "429 Too Many Requests with a Retry-After header", "403 Forbidden", "404 Not Found"]', 1, '429 means "too often", and Retry-After says after how many seconds to try again.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 3, 'What status does the server return when it agrees to switch to WebSocket?', '["200 OK", "301 Moved Permanently", "101 Switching Protocols", "426 Upgrade Required"]', 2, 'After that, WebSocket frames flow over the same TCP connection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 14, 4, 'What do you use for one-way news from the server, if you want something simple with no separate protocol?', '["Server-Sent Events: a text/event-stream response that the server never closes", "gRPC with a two-way stream", "UDP multicast", "Polling once per millisecond"]', 0, 'SSE works over plain HTTP, reconnects by itself, and can resume with Last-Event-ID.');
